-- Rollback-only acceptance of the completion release. No emails or accounts survive.
begin;
do $test$
declare teacher uuid:=gen_random_uuid(); student uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); admin uuid;
 course uuid; classroom uuid; other_class uuid; third_class uuid; copied_topic uuid; topic uuid; lab uuid; qlesson uuid; quiz uuid; question uuid; correct_option uuid; wrong_option uuid;
 tier text; tier_topic uuid; tier_lab uuid; tier_qlesson uuid; tier_quiz uuid; tier_question uuid; tier_option uuid; report_id bigint;
 s public.lesson_submissions; a public.quiz_attempts; first_request uuid:=gen_random_uuid(); result jsonb; gradebook jsonb; project uuid;
begin
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 insert into auth.users(id,email,raw_user_meta_data) values(teacher,'release-teacher-'||teacher||'@example.invalid','{"username":"Release Teacher","role":"teacher"}'),(student,'release-student-'||student||'@example.invalid','{"username":"Release Student","role":"admin"}'),(outsider,'release-outsider-'||outsider||'@example.invalid','{"username":"Release Outsider"}');
 if exists(select 1 from public.profiles where id in (teacher,student,outsider) and role<>'student') then raise exception 'Public metadata granted a privileged role.'; end if;
 update public.profiles set role='teacher',must_change_password=true where id=teacher;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',teacher,'role','authenticated')::text,true);set local role authenticated;
 if private.account_ready() then raise exception 'Temporary password account can access classroom data.';end if;
 begin update public.profiles set must_change_password=false where id=teacher;if exists(select 1 from public.profiles where id=teacher and not must_change_password) then raise exception 'Teacher bypassed password requirement';end if;exception when raise_exception then if sqlerrm='Teacher bypassed password requirement' then raise;end if;end;
 reset role;
 update auth.users set encrypted_password='acceptance-changed-password-hash' where id=teacher;
 if exists(select 1 from public.profiles where id=teacher and must_change_password) then raise exception 'Trusted password update did not finish setup.';end if;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 select id into course from public.courses where slug='html';
 insert into public.classrooms(teacher_id,name,is_active) values(teacher,'Completion acceptance fixture',true) returning id into classroom;
 insert into public.classrooms(teacher_id,name,is_active) values(teacher,'Independent copy fixture',true) returning id into other_class;
 insert into public.classroom_courses(classroom_id,course_id) values(classroom,course);
 insert into public.classroom_members(classroom_id,student_id) values(classroom,student);
 insert into public.topics(course_id,classroom_id,title,description,"order",slug,is_published,is_unlocked) values(course,classroom,'Acceptance topic','',0,'release-acceptance-'||classroom,true,true) returning id into topic;
 insert into public.lessons(topics_id,classroom_id,author,title,type,is_published,slug,mastery_checkpoint,proficiency_tier) values(topic,classroom,teacher,'Lab acceptance','laboratory',true,'lab-acceptance-'||classroom,true,'beginner') returning id into lab;
 insert into public.laboratories(lesson_id,instruction) values(lab,'{"description":"Build a profile page"}');
 insert into public.lessons(topics_id,classroom_id,author,title,type,is_published,slug,mastery_checkpoint,proficiency_tier) values(topic,classroom,teacher,'Quiz acceptance','quiz',true,'quiz-acceptance-'||classroom,true,'beginner') returning id into qlesson;
 insert into public.quizzes(lesson_id,time_limit,passing_score) values(qlesson,300,1) returning id into quiz;
 insert into public.questions(quiz_id,text,"order") values(quiz,'Choose the semantic heading',1) returning id into question;
 insert into public.options(question_id,text,is_correct) values(question,'h1',true) returning id into correct_option;
 insert into public.options(question_id,text,is_correct) values(question,'style',false) returning id into wrong_option;
 insert into public.classroom_badge_rules(classroom_id,course_id,topic_id,name,description,criterion) values(classroom,course,topic,'Acceptance mastery badge','','topic_mastered');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'role','authenticated')::text,true);
 set local role authenticated;
 s:=public.submit_laboratory(lab,'[{"filename":"index.html","code":"<h1>Draft</h1>"}]',gen_random_uuid(),true);
 if s.is_final or exists(select 1 from public.user_lesson_progress where user_id=student and lesson_id=lab and is_completed) then raise exception 'Draft incorrectly completed laboratory.'; end if;
 s:=public.submit_laboratory(lab,'[{"filename":"index.html","code":"<h1>Submission</h1>"}]',first_request,false);
 if s.score is not null or not s.is_final or s.review_status<>'submitted' or s.rubric_snapshot is null then raise exception 'Laboratory snapshot state is incorrect.'; end if;
 perform public.submit_laboratory(lab,'[{"filename":"index.html","code":"<h1>Submission</h1>"}]',first_request,false);
 if (select count(*) from public.user_xp_logs where source_id=lab and user_id=student)<>1 then raise exception 'Retry XP count: %',(select count(*) from public.user_xp_logs where source_id=lab and user_id=student); end if;
 begin perform public.grade_lab_rubric(s.id,'{"content":30,"structure":25,"application":30,"readability":15}','Forged',1);raise exception 'Student graded their own work';exception when raise_exception then if sqlerrm='Student graded their own work' then raise;end if;end;
 a:=public.begin_assessed_quiz(quiz);
 result:=public.finish_assessed_quiz(a.id,jsonb_build_array(jsonb_build_object('questionId',question,'selectedOptionId',wrong_option,'isCorrect',true)));
 if (result->>'score')::integer<>0 then raise exception 'Browser correctness claim affected quiz score.'; end if;
 a:=public.begin_assessed_quiz(quiz);
 result:=public.finish_assessed_quiz(a.id,jsonb_build_array(jsonb_build_object('questionId',question,'selectedOptionId',correct_option)));
 if (result->>'score')::integer<>1 then raise exception 'Correct server-scored answer failed.'; end if;
 perform public.finish_assessed_quiz(a.id,'[]');
 if (select count(*) from public.user_xp_logs where source_id=qlesson and user_id=student)<>1 then raise exception 'Quiz retry awarded duplicate XP.'; end if;
 if has_column_privilege('authenticated','public.options','is_correct','SELECT') then raise exception 'Student can fetch answer keys.'; end if;
 result:=public.get_course_mastery(classroom,student);
 if result->0->>'classification'<>'beginner' then raise exception 'Easy evidence incorrectly advanced proficiency.'; end if;
 project:=public.copy_learning_project(lab);
 if public.copy_learning_project(lab)<>project then raise exception 'Repeated activity completion duplicated project.'; end if;
 reset role;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',teacher,'role','authenticated')::text,true);set local role authenticated;
 s:=public.grade_lab_rubric(s.id,'{"content":15,"structure":10,"application":15,"readability":10}','Please revise structure.',1);
 if s.review_status<>'needs_revision' or s.score<>50 then raise exception 'Rubric total or revision request incorrect.'; end if;
 reset role;perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'role','authenticated')::text,true);set local role authenticated;
 s:=public.submit_laboratory(lab,'[{"filename":"index.html","code":"<main><h1>Revision</h1></main>"}]',gen_random_uuid(),false);
 if s.revision<>2 or s.score is not null or s.graded_at is not null then raise exception 'Revision retained stale grade.'; end if;
 if not exists(select 1 from public.submission_history where submission_id=s.id and snapshot->>'score'='50') then raise exception 'Prior reviewed submission was lost.'; end if;
 reset role;perform set_config('request.jwt.claims',jsonb_build_object('sub',teacher,'role','authenticated')::text,true);set local role authenticated;
 begin perform public.grade_lab_rubric(s.id,'{"content":30,"structure":25,"application":30,"readability":15}','Stale',1);raise exception 'Stale revision grade accepted';exception when raise_exception then if sqlerrm='Stale revision grade accepted' then raise;end if;end;
 s:=public.grade_lab_rubric(s.id,'{"content":25,"structure":20,"application":25,"readability":15}','Passed',2);
 if s.score<>85 or s.review_status<>'passed' then raise exception 'Passing rubric grade incorrect.'; end if;
 reset role;perform private.evaluate_classroom_badges(student,classroom);set local role authenticated;
 if (select count(*) from public.classroom_badge_awards where student_id=student and classroom_id=classroom)<>1 then raise exception 'Mastery award missing or duplicated.';end if;
 begin update public.laboratories set passing_score=80 where lesson_id=lab;raise exception 'Published rubric changed';exception when raise_exception then if sqlerrm='Published rubric changed' then raise;end if;end;
 foreach tier in array array['intermediate','advanced'] loop
 reset role;
 insert into public.topics(course_id,classroom_id,title,description,"order",slug,is_published,is_unlocked) values(course,classroom,tier,'',case when tier='intermediate' then 1 else 2 end,'release-'||tier||classroom,true,true) returning id into tier_topic;
 insert into public.lessons(topics_id,classroom_id,author,title,type,is_published,slug,mastery_checkpoint,proficiency_tier,learning_objective) values(tier_topic,classroom,teacher,tier||' lab','laboratory',true,'release-lab-'||tier||classroom,true,tier,'Demonstrate the checkpoint objective') returning id into tier_lab;
 insert into public.laboratories(lesson_id,instruction) values(tier_lab,'Build the required project');
 insert into public.lessons(topics_id,classroom_id,author,title,type,is_published,slug,mastery_checkpoint,proficiency_tier,learning_objective) values(tier_topic,classroom,teacher,tier||' quiz','quiz',true,'release-quiz-'||tier||classroom,true,tier,'Explain the checkpoint objective') returning id into tier_qlesson;
 insert into public.quizzes(lesson_id,time_limit,passing_score) values(tier_qlesson,300,1) returning id into tier_quiz;
 insert into public.questions(quiz_id,text,"order") values(tier_quiz,'Choose the correct concept',1) returning id into tier_question;
 insert into public.options(question_id,text,is_correct) values(tier_question,'Correct',true) returning id into tier_option;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'role','authenticated')::text,true);set local role authenticated;
 a:=public.begin_assessed_quiz(tier_quiz);perform public.finish_assessed_quiz(a.id,jsonb_build_array(jsonb_build_object('questionId',tier_question,'selectedOptionId',tier_option)));
 s:=public.submit_laboratory(tier_lab,'[{"filename":"index.html","code":"<h1>Checkpoint</h1>"}]',gen_random_uuid(),false);
 result:=public.get_course_mastery(classroom,student);
 if result->0->>'classification'=tier then raise exception 'Pending laboratory granted mastery.';end if;
 reset role;perform set_config('request.jwt.claims',jsonb_build_object('sub',teacher,'role','authenticated')::text,true);set local role authenticated;
 s:=public.grade_lab_rubric(s.id,'{"content":30,"structure":25,"application":30,"readability":15}','Passed all criteria',1);
 result:=public.get_course_mastery(classroom,student);
 if result->0->>'classification'<>tier then raise exception 'All prerequisite checkpoint evidence did not establish %.',tier;end if;
 end loop;
 gradebook:=public.classroom_gradebook(classroom);
 if jsonb_array_length(gradebook->'students')<>1 then raise exception 'Gradebook roster incorrect.'; end if;
 perform public.clone_course_to_classroom(other_class,course);
 if not exists(select 1 from public.classroom_courses where classroom_id=other_class and course_id=course) then raise exception 'Template import failed.'; end if;
 insert into public.classrooms(teacher_id,name,is_active) values(teacher,'Second independent import',true) returning id into third_class;
 perform public.clone_course_to_classroom(third_class,course);
 if (select count(*) from public.lessons le join public.topics t on t.id=le.topics_id where t.course_id=course and le.classroom_id=other_class)<>(select count(*) from public.lessons le join public.topics t on t.id=le.topics_id where t.course_id=course and le.classroom_id is null) then raise exception 'Import lost lessons.';end if;
 select id into copied_topic from public.topics where classroom_id=other_class and course_id=course order by "order" limit 1;
 update public.topics set title='Edited classroom copy' where id=copied_topic;
 if exists(select 1 from public.topics where classroom_id=third_class and title='Edited classroom copy') or exists(select 1 from public.topics where classroom_id is null and title='Edited classroom copy') then raise exception 'Classroom edits changed another copy.';end if;
 reset role;
 if exists(select 1 from public.lessons cp join public.topics ct on ct.id=cp.topics_id join public.topics mt on mt.course_id=ct.course_id and mt.classroom_id is null and mt.slug=ct.slug join public.lessons master on master.topics_id=mt.id and master.slug=cp.slug where cp.classroom_id=other_class and (cp.proficiency_tier,cp.mastery_checkpoint,cp.learning_objective) is distinct from (master.proficiency_tier,master.mastery_checkpoint,master.learning_objective)) then raise exception 'Import lost assessment metadata.';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',teacher,'role','authenticated')::text,true);set local role authenticated;
 result:=public.get_classroom_student_review(classroom,student);
 if not exists(select 1 from jsonb_array_elements(result->'lessons') le cross join lateral jsonb_array_elements(le->'attempts') at1 where jsonb_array_length(at1->'answers')>0) then raise exception 'Quiz answer history missing.';end if;
 reset role;perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'role','authenticated')::text,true);set local role authenticated;
 if exists(select 1 from public.submission_history where submission_id=s.id) then raise exception 'Outsider accessed submission history.'; end if;
 begin perform public.classroom_gradebook(classroom);raise exception 'Outsider opened gradebook';exception when raise_exception then if sqlerrm='Outsider opened gradebook' then raise;end if;end;
 reset role;
 insert into public.quiz_attempts(user_id,quiz_id,score,status,finished_at) values(student,quiz,1,'failed',now()) returning * into a;
 insert into public.quiz_answers(attempt_id,question_id,options_id,is_correct) values(a.id,question,correct_option,true);
 if private.quiz_attempt_percent(a)<>100 then raise exception 'Historical raw-count attempt displayed as a percentage.';end if;
 a.score:=95;
 if private.quiz_attempt_percent(a)<>95 then raise exception 'Historical percentage grade was rescaled.';end if;
 a.score:=1;a.score_total:=2;
 if private.quiz_attempt_percent(a)<>50 then raise exception 'Published quiz denominator was ignored.';end if;
 update auth.users set banned_until=now()+interval '1 day' where id=student;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'role','authenticated')::text,true);set local role authenticated;
 if exists(select 1 from public.lessons where classroom_id=classroom) then raise exception 'Disabled account retained classroom access.';end if;
 begin perform public.begin_assessed_quiz(quiz);raise exception 'Disabled account started quiz';exception when raise_exception then if sqlerrm='Disabled account started quiz' then raise;end if;end;
 reset role;
end $test$;
rollback;
